import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·36","description":"易小帖 - 卷一·36","frontmatter":{"title":"卷一·36","description":"易小帖 - 卷一·36"},"headers":[],"relativePath":"classics/yixiaotie/036.md","filePath":"classics/yixiaotie/036.md"}'),o={name:"classics/yixiaotie/036.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·36",tabindex:"-1"},[r("卷一·36 "),e("a",{class:"header-anchor",href:"#卷一·36","aria-label":"Permalink to “卷一·36”"},"​")],-1),e("p",null,"頤二五皆有「拂經」語，舊不得其解。謂二養於初，五養於上，為反常。按爻詞並無初上養人二五就養之義。且古雲：無野人莫養君子。又雲：諸縱生盡以養一丈夫。則下原有養上之義，即上就下養，未為反常。至於上之養下，則養賢及民，本文有之，又不待言也。且未有六五二字即接反常而可以成爻詞者。（六四顛頤拂經，六五拂經。）凡經有數義，今字書所載，止有經緯、經常、經界、經過諸釋，並不及經臟、經路二義，固屬缺陋。而至於解易，則率以經常概之，殊不知頤之拂經，本讀作徑去聲，謂吭也。吭為氣經，如徑之出入，故讀徑，此即莊子之所謂緣督為經，《淮南子》之所為熊經鳥呻者，蓋督為中脈，下貫尾閭，上合齗交，而歸其氣於喉吭之間，如雲引脈作吭者，至於熊經。則莊子司馬彪註原雲：如熊之攀樹引氣，鳥之仰吭頻呻，而諸儒音讀皆作去聲，則明明以熊經為熊之引吭，經者吭也。自郭象註莊，不曉此義，但註經為常，而至於熊經，則無可引據，遂至矇昧。夫經之為吭，不止引吭為然也。考《漢書》列傳以貫高縊死為絶吭而死，而諸書縊死皆作經死，如《論語》自經溝瀆，《荀子》救經引足類，亦惟經即是吭，故既可稱經，亦可稱吭，蓋縊處在經，即謂之經，如走處在腓，即謂之腓，覆處在翼，即謂之翼。《小雅》小人所腓，《孟子》輔之翼之是也。（舊以經解縊非是。）況引吭曰熊經，絶吭曰雉經。引吭絶吭，總皆以禽獸為喻，雖雉飛熊走族類，不一然。猶是仰吭而在引氣則謂之熊經，在絶吭則謂之雉經。其為經同，而所以為經不同者，止以熊善養氣，雉易搶死，故有殊耳。實則易之拂經，莊子之緣經，淮南子之熊經，國語之雉經，只是一經，故熊經讀徑，雉經亦讀徑。陸德明之註曰如字，亦仍不甚解而誤為正定者也。若韋昭註雉經，但雲縊死，而諸家以雉字解雉性耿介，頭搶屈折皆不為過。獨孔仲達作《檀弓疏》引鄭註雉經字，謂康成曾以絼箸牛鼻繩註雲：今人稱之為雉，遂以雉經為牛鼻繩所縊而死。則未免杜撰。但仲達又雲：《漢書》所載，趙人貫高絶吭而死申生雉經，當亦如是。此是實據，而字書蔑裂竟失此義陋矣。若頤之拂經，則正與頤類及者。朶頤、拂經皆欲食之狀，何精核也。詳見予本卦註下。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
